<span class="line"><span class="__shiki_140thh">    id UUID </span><span class="__shiki_1itgoe">PRIMARY KEY</span><span class="__shiki_1itgoe"> DEFAULT</span><span class="__shiki_140thh"> gen_random_uuid(),</span></span>
